code='''from collections import Counter, deque


def transform(grid):
    """Fill enclosed background regions: odd-sized holes with 7, even with 2."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    outside = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == bg and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == bg and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg and (nr,nc) not in outside:
                outside.add((nr,nc)); q.append((nr,nc))
    out = [row[:] for row in grid]
    seen = set(outside)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            region = []
            while q:
                x,y=q.popleft(); region.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == bg and (nx,ny) not in seen:
                        seen.add((nx,ny)); q.append((nx,ny))
            fill = 2 if len(region) % 2 == 0 else 7
            for x,y in region:
                out[x][y] = fill
    return out
